package cn.local.accountmanager.core;

import org.junit.Test;
import static org.junit.Assert.*;
import static cn.local.accountmanager.core.LoginJson.*;
import java.util.*;
import java.net.URI;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;

public final class OAuthLoginTest {
    public static String tokens(OAuthLogin.Provider provider){
        String id="header."+Base64.getUrlEncoder().withoutPadding().encodeToString(encode(object("email","alice@example.com","https://api.openai.com/auth",object("chatgpt_account_id","acct-demo","chatgpt_user_id","user-demo","chatgpt_plan_type","plus"))).getBytes(StandardCharsets.UTF_8))+".synthetic";
        return encode(provider==OAuthLogin.Provider.OPENAI?object("access_token","synthetic-access","refresh_token","synthetic-refresh","id_token",id,"expires_in",3600):object("access_token","synthetic-claude-access","refresh_token","synthetic-claude-refresh","expires_in",3600,"account",object("email_address","alice@example.com","uuid","account-demo"),"organization",object("uuid","org-demo")));
    }
    private void reject(Runnable action){assertThrows(IllegalArgumentException.class,action::run);}
    @Test public void pkceRandomnessAndHash()throws Exception{
        for(var provider:OAuthLogin.Provider.values()){
            OAuthLogin f=new OAuthLogin(provider,"alice@example.com"),other=new OAuthLogin(provider,"");assertEquals(43,f.verifier.length());assertEquals(43,f.state.length());assertNotEquals(f.state,other.state);assertNotEquals(f.verifier,other.verifier);
            URI uri=URI.create(f.authorizationUrl());assertEquals("https",uri.getScheme());Map<String,String> q=OAuthLogin.query(uri.getRawQuery());assertEquals(f.redirect(),q.get("redirect_uri"));assertEquals("S256",q.get("code_challenge_method"));assertEquals(f.state,q.get("state"));assertEquals(Base64.getUrlEncoder().withoutPadding().encodeToString(MessageDigest.getInstance("SHA-256").digest(f.verifier.getBytes(StandardCharsets.US_ASCII))),q.get("code_challenge"));assertFalse(f.authorizationUrl().contains(f.verifier));
        }
    }
    @Test public void providerEndpoints(){OAuthLogin a=new OAuthLogin(OAuthLogin.Provider.OPENAI,""),b=new OAuthLogin(OAuthLogin.Provider.CLAUDE,"");assertEquals("https://auth.openai.com/oauth/token",a.tokenEndpoint());assertEquals("https://platform.claude.com/v1/oauth/token",b.tokenEndpoint());assertEquals("http://localhost:1455/auth/callback",a.redirect());assertEquals("http://localhost:54545/callback",b.redirect());}
    @Test public void callbackAndOneTimeExchange(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");String url=f.redirect()+"?code=demo%2Bcode&state="+f.state;assertEquals("demo+code",f.validateCallback(url));Map<String,Object> body=f.takeExchange(url);assertEquals(f.verifier,body.get("code_verifier"));assertEquals(f.redirect(),body.get("redirect_uri"));assertEquals(f.clientId(),body.get("client_id"));assertEquals(p==OAuthLogin.Provider.CLAUDE,body.containsKey("state"));reject(()->f.takeExchange(url));}}
    @Test public void callbackOriginStatePathAndDuplicateRejection(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");String u=f.redirect()+"?code=demo&state="+f.state;for(String bad:new String[]{u.replace("http:","https:"),u.replace("localhost","localhost.evil.invalid"),u.replace("localhost","127.0.0.1"),u.replace("localhost","user@localhost"),u.replace(":"+f.port(),":8888"),u.replace(URI.create(f.redirect()).getPath(),"/other"),u+"#fragment",u+"&state="+f.state,u+"&code=other",u.replace(f.state,"other"),f.redirect()+"?state="+f.state,"demo","",null})reject(()->f.validateCallback(bad));}}
    @Test public void callbackDenial(){OAuthLogin f=new OAuthLogin(OAuthLogin.Provider.OPENAI,"");reject(()->f.validateCallback(f.redirect()+"?error=access_denied&state="+f.state));assertTrue(f.isDenial(f.redirect()+"?error=access_denied&state="+f.state));assertFalse(f.isDenial(f.redirect()+"?error=access_denied&state=other"));}
    @Test public void openaiIdentity(){OAuthLogin f=new OAuthLogin(OAuthLogin.Provider.OPENAI,"ALICE@EXAMPLE.COM");var c=f.parseTokens(tokens(f.provider),System.currentTimeMillis());assertEquals("alice@example.com",c.email);assertEquals("acct-demo",c.accountId);assertEquals("user-demo",c.userId);assertEquals("plus",c.plan);assertEquals(3600000,c.expires-c.created);}
    @Test public void claudeIdentity(){OAuthLogin f=new OAuthLogin(OAuthLogin.Provider.CLAUDE,"alice@example.com");var c=f.parseTokens(tokens(f.provider),System.currentTimeMillis());assertEquals("account-demo",c.accountId);assertEquals("org-demo",c.organization);assertEquals("",c.idToken);}
    @Test public void wrongAccountRejected(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"bob@example.com");reject(()->f.parseTokens(tokens(p),System.currentTimeMillis()));}}
    @Test public void refreshTokenRequired(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");Map<String,Object> t=map(decode(tokens(p)));t.remove("refresh_token");reject(()->f.parseTokens(encode(t),System.currentTimeMillis()));}}
    @Test public void tokenExpiryMustBeBoundedInteger(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");for(Object expiry:Arrays.asList(0,-1,31536001,1.5,"bad")){Map<String,Object> t=map(decode(tokens(p)));t.put("expires_in",expiry);reject(()->f.parseTokens(encode(t),System.currentTimeMillis()));}}}
    @Test public void incompleteAndInvalidTokens(){OAuthLogin f=new OAuthLogin(OAuthLogin.Provider.OPENAI,"");for(String json:new String[]{"{}","[]","null","{","\"string\""})reject(()->f.parseTokens(json,System.currentTimeMillis()));Map<String,Object> t=map(decode(tokens(f.provider)));t.put("id_token","header.e30.signature");reject(()->f.parseTokens(encode(t),System.currentTimeMillis()));}
    @Test public void cpaMatchesProviderTokenStorage(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");var c=f.parseTokens(tokens(p),System.currentTimeMillis());Map<String,Object> out=map(decode(c.export(false)));assertEquals(p==OAuthLogin.Provider.OPENAI?"codex":"claude",out.get("type"));assertEquals(c.access,out.get("access_token"));assertEquals(c.refresh,out.get("refresh_token"));assertEquals(c.accountId,out.get(p==OAuthLogin.Provider.OPENAI?"account_id":"account_uuid"));assertNotNull(out.get("expired"));}}
    @Test public void sub2apiNativeDataBundle(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");var c=f.parseTokens(tokens(p),System.currentTimeMillis());Map<String,Object> out=map(decode(c.export(true)));assertEquals("sub2api-data",out.get("type"));assertEquals(1L,out.get("version"));assertEquals(Collections.emptyList(),out.get("proxies"));List<?> list=(List<?>)out.get("accounts");assertEquals(1,list.size());Map<String,Object> a=map(list.get(0));assertEquals(p==OAuthLogin.Provider.OPENAI?"openai":"anthropic",a.get("platform"));assertEquals("oauth",a.get("type"));assertEquals(1L,a.get("concurrency"));assertEquals(c.access,map(a.get("credentials")).get("access_token"));if(p==OAuthLogin.Provider.CLAUDE)assertEquals("org-demo",map(a.get("credentials")).get("org_uuid"));}}
    @Test public void exportsExcludeHistoryAndLoginSecrets(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");var c=f.parseTokens(tokens(p),System.currentTimeMillis());String output=c.export(false)+c.export(true);assertFalse(output.contains("password"));assertFalse(output.contains("otpauth"));assertFalse(output.contains("code_verifier"));assertFalse(output.contains(f.state));assertFalse(output.contains(f.verifier));}}
    @Test public void expiredCredentialsNeverExport(){for(var p:OAuthLogin.Provider.values()){OAuthLogin f=new OAuthLogin(p,"");var c=f.parseTokens(tokens(p),System.currentTimeMillis()-86400000);reject(()->c.export(false));reject(()->c.export(true));}}
    @Test public void exactHttpsOriginsOnly(){for(var p:OAuthLogin.Provider.values()){String host=p==OAuthLogin.Provider.OPENAI?"auth.openai.com":"claude.ai";assertTrue(OAuthLogin.allowsFill(p,URI.create("https://"+host+"/login")));for(String u:new String[]{"http://"+host,"https://"+host+".evil.invalid","https://user@"+host,"https://"+host+":8443","https://accounts.google.com","file:///login"})assertFalse(OAuthLogin.allowsFill(p,URI.create(u)));}}
    @Test public void jsonEscapesUnicodeAndControls(){Map<String,Object> v=object("中文😀","引号\"换行\n反斜线\\\t","array",Arrays.asList(true,false,null,1L));assertEquals(v,decode(encode(v)));}
    @Test public void jsonRejectsDuplicateAndMalformed(){for(String s:new String[]{"{\"a\":1,\"a\":2}","{\"a\":1,}","[1,]","01","NaN","\"\\q\"","true false","{","\"raw\nline\""})reject(()->decode(s));}
}
